    this.todoWindow = true;
    this.playing = false; // \u{662F}\u{5426}\u{5728}\u{64AD}\u{653E}
    this.buffering = false; // pcm \u{64AD}\u{653E}\u{5668}\u{662F}\u{5426}\u{63A5}\u{53D7}\u{5230}\u{6570}\u{636E}
    // this.running = false; // \u{7528}\u{6237}\u{662F}\u{5426}\u{624B}\u{52A8}\u{8868}\u{660E}tts\u{6570}\u{636E}\u{5DF2}\u{5B8C}\u{6BD5}
    this.mode = "auto"; // \u{9ED8}\u{8BA4}\u{624B}\u{52A8}\u{6D41}\u{8F6C}\u{6A21}\u{5F0F}
